const raw = String($input.first().json.text ?? '').trim();
const cleaned = raw
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    'Gagal parse JSON dari Basic LLM Chain: ' + error.message +
    '\n\nRaw output:\n' + raw
  );
}

const validCategories = [
  'Adventure', 'Agenda', 'Bengkel', 'CSR', 'Dealer', 'Formula 1',
  'Grasstrack', 'Internasional', 'Karting', 'Komunitas', 'Modifikasi',
  'Moto2', 'Moto3', 'MotoGP', 'Motocross', 'Motor Klasik', 'News',
  'Offroad', 'Produk', 'Profile', 'Rally', 'Road Race', 'Safety Riding',
  'Tips & Trik', 'WSBK'
];

const text = (value) => String(value ?? '').trim();
const category = validCategories.includes(text(parsed.category))
  ? text(parsed.category)
  : 'News';
const headline = 'UJI SERENTAK TELEGRAM';
const subheadline = 'Dua anggota menguji keputusan pertama yang valid.';
const caption = 'Salam Otozoner!\n\nIni pesan uji alur approval Telegram. Tidak ada konten yang dikirim ke Instagram.\n\nBaca ulasan lengkapnya di sini!\nKlik link di bio!\n\n#OtomotifZone';
const warnings = [];

if (category !== text(parsed.category)) warnings.push('Kategori AI tidak valid; diubah menjadi News.');
if (headline.split(/\s+/).filter(Boolean).length > 12) warnings.push('Headline melebihi 12 kata.');
if ([...headline].length > 80) warnings.push('Headline melebihi 80 karakter.');
if (subheadline.split(/\s+/).filter(Boolean).length > 20) warnings.push('Subheadline melebihi 20 kata.');
if (!caption.startsWith('Salam Otozoner!')) warnings.push('Pembuka caption tidak sesuai.');
if (!caption.includes('Baca ulasan lengkapnya di sini!\nKlik link di bio!')) warnings.push('CTA caption tidak sesuai.');
const hashtags = caption.match(/#[\p{L}\p{N}_]+/gu) || [];
if (hashtags.length > 5) warnings.push('Hashtag melebihi 5.');
if (hashtags[0] !== '#OtomotifZone') warnings.push('#OtomotifZone bukan hashtag pertama.');

return [{
  json: {
    category,
    confidence: Number.isFinite(Number(parsed.confidence)) ? Number(parsed.confidence) : 0,
    author: text(parsed.author) || 'Tim Redaksi',
    headline,
    subheadline,
    caption,
    source_link: text(parsed.source_link),
    image_url: text(parsed.image_url),
    validation_warnings: warnings
  }
}];

const item = $input.first().json;
let caption = item.caption || '';

caption = caption.replace(/\r\n/g, '\n');
caption = caption.replace(/Salam Otozoner!\s*/i, 'Salam Otozoner!\n\n');
caption = caption.replace(/\s*Baca ulasan lengkapnya di sini!\s*/i, '\n\nBaca ulasan lengkapnya di sini!\n');
caption = caption.replace(/\s*Klik link di bio!\s*/i, '\nKlik link di bio!\n\n');
caption = caption.replace(/\s+(#OtomotifZone\b)/i, '\n\n#OtomotifZone');
caption = caption.replace(/\n{3,}/g, '\n\n').trim();

const warnings = Array.isArray(item.validation_warnings)
  ? item.validation_warnings
  : [];
const warningBlock = warnings.length
  ? '\n\nPERINGATAN:\n- ' + warnings.join('\n- ')
  : '';

const telegramCaption =
  'Kategori: ' + (item.category || '-') + '\n' +
  'Confidence: ' + (item.confidence ?? 0) + '%' + '\n\n' +
  'Penulis: ' + (item.author || '-') + '\n\n' +
  'HEADLINE:\n' + (item.headline || '-') + '\n\n' +
  'SUBHEADLINE:\n' + (item.subheadline || '-') + '\n\n' +
  'CAPTION:\n' + (caption || '-') +
  warningBlock + '\n\n' +
  'Source: ' + (item.source_link || '-');

return [{
  json: {
    ...item,
    caption,
    telegram_caption: telegramCaption,
    needs_review: warnings.length > 0
  }
}];

